mapper.select:
select id, words, url, sort, fraction, title, is_end isEnd, delicate, author, introduce, del_status, up_status, create_time, update_time from t_ebook where up_status=1 and del_status=1 and is_end=#{isEnd}
and words < 500000 and words >= 500000 and words < 1000000 and words >= 1000000 and words < 2000000 and words >= 2000000
order by update_time desc,sort asc order by fraction desc,update_time desc order by words desc,update_time desc order by sort asc,update_time desc

SELECT e.id, e.words, e.url, e.sort, e.fraction, e.title, e.is_end isEnd, e.delicate, e.author, e.introduce, e.del_status, e.up_status, e.create_time, e.update_time from t_ebook_category_info ci INNER JOIN t_ebook e on e.id=ci.ebook_id where e.up_status=1 and e.del_status=1 and ci.category_id=#{categoryId} and e.is_end=#{isEnd}
and e.words < 500000 and e.words >= 500000 and words < 1000000 and e.words >= 1000000 and words < 2000000 and e.words >= 2000000
order by e.update_time desc,sort asc order by e.fraction desc,update_time desc order by e.words desc,update_time desc order by e.sort asc,update_time desc
